window.HOEREN_TESTS[42] = {"id":"reise-mit-dem-auto","name":"Reise mit dem Auto","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Achtung Autofahrer auf der A8: Wir haben einen Stau auf 15 Kilometer wegen eines Unfalls. Die linke Spur ist gesperrt. Bitte mit 50 km/h fahren. Bitte bleiben Sie nicht auf der A8 stehen, wir empfehlen die Ausfahrt Ulm — über die Landstraße kommen Sie 30 Minuten schneller voran.","gender":"f","q":"Was wird empfohlen?","opts":["Ausfahrt Ulm nehmen.","Auf der A8 bleiben.","Pause machen."],"correct":0},{"transcript":"Hallo Lisa, hier ist Anna. Du, ich stehe im Stau auf der Autobahn. Komme später, etwa 18 Uhr statt 17. Sorry! Spätestens um 19 Uhr bin ich sicher da, versprochen. Bitte fang ohne mich mit dem Essen an. Tom kommt pünktlich. Ich rufe wieder an, wenn ich näher bin. Bis später, freu mich!","gender":"f","q":"Wann kommt Anna jetzt?","opts":["18 Uhr.","17 Uhr.","19 Uhr."],"correct":0},{"transcript":"Hi Markus, mein Auto ist kaputt. Die Batterie ist tot — heute Morgen wollte ich starten, nichts. Der Motor ist in Ordnung und die Reifen sind neu, nur die Batterie ist tot. Kannst du mich am Bahnhof abholen um 15 Uhr? Nehme den Zug ins Büro. Sonst muss ich Taxi nehmen, viel zu teuer. Ruf bitte zurück, danke!","gender":"m","q":"Was ist das Problem?","opts":["Der Motor läuft nicht.","Die Batterie ist tot.","Reifen platt."],"correct":1},{"transcript":"Liebe Kunden des Park-Hauses Sonne: Ab Montag haben wir neue Preise. Stunde 3 Euro statt 2 Euro 50. Tagesticket 25 Euro statt 22. Monatskarte 200 Euro statt 180. Wer länger als eine Woche parkt, zahlt pauschal 30 Euro extra. Wir entschuldigen uns für die Erhöhung — wegen steigender Kosten unvermeidlich. Vielen Dank. Danke für Ihr Verständnis!","gender":"m","q":"Was kostet ein Tagesticket jetzt?","opts":["22 Euro.","25 Euro.","30 Euro."],"correct":1},{"transcript":"Hallo Tom, hier ist Vater. Ich brauche das Auto morgen — habe Termin beim Arzt. Nicht zum Einkaufen und nicht für deine Treffen mit Freunden, nur für den Arzt. Du musst mit dem Bus fahren ins Büro, sorry. Oder Fahrrad, falls Wetter gut ist. Auf jeden Fall: Auto bleibt bei mir. Frag bitte nicht. Ruf zurück, wenn Probleme.","gender":"m","q":"Warum braucht Vater das Auto?","opts":["Einkaufen.","Treffen mit Freunden.","Arzt-Termin."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer fährt was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Am Samstag fahren wir zusammen in den Süden."},{"speaker":"Lisa","gender":"f","text":"Hallo Lukas! Fünf Wagen stehen in der Einfahrt. Wer nimmt welchen?"},{"speaker":"Lukas","gender":"m","text":"Mein Wagen für die Strecke ist der BMW. Damit bin ich auf der Autobahn schnell."},{"speaker":"Lisa","gender":"f","text":"Dann bist du als Erster an der Raststätte. Ich brauche unterwegs Strom."},{"speaker":"Lukas","gender":"m","text":"Kommt noch jemand in einem Porsche?"},{"speaker":"Lisa","gender":"f","text":"Nein. Ein Porsche kommt nicht mit."},{"speaker":"Lukas","gender":"m","text":"Du hast den leisen Wagen mit der großen Batterie."},{"speaker":"Lisa","gender":"f","text":"Ich sitze im Tesla. An der Raststätte kann ich in Ruhe laden."},{"speaker":"Lukas","gender":"m","text":"Tom nimmt die Familie und alle Koffer mit."},{"speaker":"Lisa","gender":"f","text":"Tom fährt den VW Bus. Hinten passen die Taschen gut rein."},{"speaker":"Lukas","gender":"m","text":"Sara sucht etwas Kleines für enge Straßen."},{"speaker":"Lisa","gender":"f","text":"Sara kommt im Mini Cooper. Der passt in jede Parklücke."},{"speaker":"Lukas","gender":"m","text":"Hat noch jemand einen Audi?"},{"speaker":"Lisa","gender":"f","text":"Nein. Einen Audi hat auch keiner."},{"speaker":"Lukas","gender":"m","text":"Tim kommt direkt nach der Arbeit zu uns."},{"speaker":"Lisa","gender":"f","text":"Tim bringt den Mercedes mit. Der Wagen ist ruhig und dunkel."},{"speaker":"Lukas","gender":"m","text":"Wir treffen uns um acht an der Tankstelle."},{"speaker":"Lisa","gender":"f","text":"Ich schicke den anderen noch die genaue Uhrzeit."}],"options":[{"letter":"a","text":"Porsche"},{"letter":"b","text":"Tesla"},{"letter":"c","text":"Audi"},{"letter":"d","text":"BMW"},{"letter":"e","text":"Ford"},{"letter":"f","text":"Mercedes"},{"letter":"g","text":"Opel"},{"letter":"h","text":"Mini Cooper"},{"letter":"i","text":"VW Bus"}],"items":[{"person":"Lukas","correct":"d"},{"person":"Lisa","correct":"b"},{"person":"Tom","correct":"i"},{"person":"Sara","correct":"h"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Volltanken, bitte."},{"speaker":"Tankwart","gender":"m","text":"Gerne! Diesel oder Super? Wir haben auch Strom für Elektroautos."},{"speaker":"Kundin","gender":"f","text":"Super, bitte. Kein Diesel, ich fahre Benziner."},{"speaker":"Tankwart","gender":"m","text":"Alles klar, Super! Das macht 75 Euro 50, bitte."},{"speaker":"Kundin","gender":"f","text":"Mit Karte, bitte. Und die Scheiben kurz putzen? Danke!"},{"speaker":"Kundin","gender":"f","text":"Gut, dann tanke ich Super. Mit Karte, bitte, und tschüss!"}],"q":"Was tankt die Kundin?","opts":["Diesel.","Super.","Strom."],"correct":1},{"lines":[{"speaker":"Fahrerin","gender":"f","text":"Wie lange dauert die Fahrt nach München ohne Pausen?"},{"speaker":"Beifahrer","gender":"m","text":"Ohne Stau etwa 3 Stunden, ganz direkt."},{"speaker":"Fahrerin","gender":"f","text":"Und mit Pausen? Vier Stunden oder fünf?"},{"speaker":"Beifahrer","gender":"m","text":"Mit einer Pause vier Stunden. Fünf Stunden brauchen wir sicher nicht."},{"speaker":"Fahrerin","gender":"f","text":"Gut, dann fahren wir direkt. In drei Stunden sind wir da! Ich freue mich schon!"}],"q":"Wie lange ohne Pausen?","opts":["4 Stunden.","3 Stunden.","5 Stunden."],"correct":1},{"lines":[{"speaker":"Vater","gender":"m","text":"Lukas, bitte schnall dich an, wir fahren los!"},{"speaker":"Lukas","gender":"m","text":"Papa, es ist doch nicht weit. Muss das sein?"},{"speaker":"Vater","gender":"m","text":"Ja, immer! Wir steigen jetzt nicht mehr aus, der Gurt bleibt an. Sicherheit zuerst!"},{"speaker":"Lukas","gender":"m","text":"Okay, okay, ich tu es ja schon. Brauche ich auch einen Helm?"},{"speaker":"Vater","gender":"m","text":"Nein, Helm nur fürs Fahrrad. Der Gurt reicht im Auto."}],"q":"Was muss Lukas tun?","opts":["Helm aufsetzen.","Aussteigen.","Anschnallen."],"correct":2},{"lines":[{"speaker":"Werkstattmeisterin","gender":"f","text":"Guten Tag! Ihr Auto ist fertig, neue Bremsen, Service erledigt."},{"speaker":"Kunde","gender":"m","text":"Schön! Wie viel kostet das? 500 Euro?"},{"speaker":"Werkstattmeisterin","gender":"f","text":"Leider mehr, 650 Euro. Die alten Bremsen waren schlimmer als gedacht."},{"speaker":"Kunde","gender":"m","text":"650 Euro! Und 750 wären es nicht, oder?"},{"speaker":"Werkstattmeisterin","gender":"f","text":"Nein, keine 750. Genau 650 Euro, mit Rechnung."},{"speaker":"Kunde","gender":"m","text":"Okay, Sicherheit zählt. Hier ist meine Karte."}],"q":"Wie viel zahlt der Kunde?","opts":["650 Euro.","500 Euro.","750 Euro."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, fährst du mich heute mit dem Auto zur Schule?"},{"speaker":"Vater","gender":"m","text":"Heute kann ich leider nicht. Nimm den Bus oder das Fahrrad."},{"speaker":"Tochter","gender":"f","text":"Das Fahrrad geht nicht, es regnet. Und der Bus dauert so lange."},{"speaker":"Vater","gender":"m","text":"Trotzdem, heute musst du den Bus nehmen. Morgen fahre ich dich wieder."},{"speaker":"Tochter","gender":"f","text":"Na gut, dann nehme ich den Bus. Tschüss, Papa!"}],"q":"Wie fährt die Tochter?","opts":["Mit dem Bus.","Mit dem Auto.","Mit dem Fahrrad."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Schubert, einem Fahrlehrer. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporterin","gender":"f","text":"Herr Schubert, Sie sind seit 30 Jahren Fahrlehrer. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Schubert","gender":"m","text":"Mein Vater hatte eine kleine Fahrschule, ich bin damit aufgewachsen. Erst wollte ich Mechaniker werden, habe das auch gelernt. Aber dann hat mein Vater mich gefragt, ob ich nicht übernehmen möchte. Heute besitze ich die Schule."},{"speaker":"Reporterin","gender":"f","text":"Wie ist die heutige Generation Fahrschüler?"},{"speaker":"Schubert","gender":"m","text":"Anders als früher. Viele 18-Jährige haben keine Eile mehr — manche machen Führerschein erst mit 22 oder 25. Auto ist nicht mehr Symbol von Freiheit wie damals. Aber wenn sie kommen, lernen sie ernster — mehr Bewusstsein."},{"speaker":"Reporterin","gender":"f","text":"Wie lange dauert ein Führerschein heute?"},{"speaker":"Schubert","gender":"m","text":"Im Durchschnitt 5 Monate. Mindestens 30 Fahrstunden, plus 12 Theoriestunden. Bei manchen schneller, bei manchen ein Jahr — kommt auf das Talent an. Mehr Theorie als früher, viele neue Verkehrsregeln."},{"speaker":"Reporterin","gender":"f","text":"Was ist der häufigste Fehler bei der Prüfung?"},{"speaker":"Schubert","gender":"m","text":"Schulterblick vergessen. Das ist ein Klassiker — der Prüfer achtet sofort darauf. Und Geschwindigkeit nicht einhalten — in der 30-Zone schneller als 30, das ist gleich ein Fehler. Stress macht viele unaufmerksam."},{"speaker":"Reporterin","gender":"f","text":"Werden Elektroautos in Fahrschulen genutzt?"},{"speaker":"Schubert","gender":"m","text":"Bei uns noch nicht — für ein Schulauto zu teuer. Aber das kommt sicher. In großen Städten schon erste Fahrschulen mit Elektro. In 10 Jahren wird das Standard sein, glaube ich."}],"items":[{"q":"Heute wollen alle 18-Jährigen sofort den Führerschein.","correct":"nein"},{"q":"Herr Schubert hat erst eine andere Ausbildung gemacht.","correct":"ja"},{"q":"Ein Führerschein dauert im Durchschnitt 5 Monate.","correct":"ja"},{"q":"Der häufigste Fehler ist Geschwindigkeit nicht einhalten.","correct":"nein"},{"q":"Seine Fahrschule hat schon Elektroautos.","correct":"nein"}]}]};
